package vn.edu.hcmute.example3; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="users") public class AppUser {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=50) private String username; @Column(nullable=false,unique=true) private String email; @Column(nullable=false) private String password; @Column(nullable=false) private String fullName; private String imageUrl; @Column(nullable=false) private String role; @Column(nullable=false) private boolean enabled; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); protected AppUser(){} public AppUser(String username,String email,String password,String fullName,String role,boolean enabled){this.username=username;this.email=email;this.password=password;this.fullName=fullName;this.role=role;this.enabled=enabled;} public Long getId(){return id;} public String getUsername(){return username;} public String getEmail(){return email;} public String getPassword(){return password;} public String getFullName(){return fullName;} public String getImageUrl(){return imageUrl;} public String getRole(){return role;} public boolean isEnabled(){return enabled;} public void activate(){enabled=true;} public void changePassword(String password){this.password=password;} }
